// Optional local test dependency; never used by the application.
import { pathToFileURL } from 'node:url';
const { PGlite } = await import(process.env.PGLITE_MODULE
  ? pathToFileURL(process.env.PGLITE_MODULE).href : '@electric-sql/pglite');
import { readFile } from 'node:fs/promises';
export const migrationUrl = new URL('../../supabase/migrations/20260827110343_multi_idea_images.sql', import.meta.url);
export async function createDatabase() {
  const db = new PGlite();
  await db.exec(`
    create role anon; create role authenticated; create role service_role bypassrls;
    -- Match the live project's explicit anonymous function default grant.
    alter default privileges in schema public grant execute on functions to anon,authenticated,service_role;
    create schema auth; create schema storage;
    grant usage on schema public,auth,storage to authenticated,anon,service_role;
    create function auth.uid() returns uuid language sql stable as $$
      select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid
    $$;
    create table public.ideas(id uuid primary key default gen_random_uuid(),title text not null,
      status text default 'アイデア',note text,tags text,image_url text,created_at timestamptz default now(),
      updated_at timestamptz default now(),deleted_at timestamptz);
    create table public.idea_items(id bigint generated by default as identity primary key,
      parent_idea_id text not null,title text not null,status text not null default 'アイデア',note text not null default '',
      image_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
    create table storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text not null,name text not null,unique(bucket_id,name));
    alter table public.ideas enable row level security;
    alter table public.idea_items enable row level security;
    alter table storage.objects enable row level security;
    create policy ideas_shared on public.ideas for all to authenticated using(true) with check(true);
    create policy items_shared on public.idea_items for all to authenticated using(true) with check(true);
    create policy storage_read on storage.objects for select to public using(bucket_id='idea-images');
    create policy storage_insert on storage.objects for insert to authenticated with check(bucket_id='idea-images');
    grant select,insert,update,delete on public.ideas,public.idea_items,storage.objects to authenticated;
    grant usage,select on all sequences in schema public to authenticated;
    grant select on public.ideas,public.idea_items to anon;
  `);
  await db.exec(await readFile(migrationUrl,'utf8'));
  await db.exec(`set role authenticated; select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',false);`);
  return db;
}
export async function save(db, kind, id, values, urls, oldUrls=[], oldTime=null) {
  return appendImages(db,kind,id,values,urls.filter(url=>!oldUrls.includes(url)),oldUrls.filter(url=>!urls.includes(url)),oldUrls,oldTime);
}
export async function appendImages(db,kind,id,values,added=[],removed=[],oldUrls=[],oldTime=null) {
  return (await db.query('select public.save_idea_with_images($1,$2,$3,$4,$5,$6,$7) result',[kind,id,JSON.stringify(values),added,removed,oldUrls,oldTime])).rows[0].result;
}
